"""The mixer's fader: only deck A at 0 and only B at 1, each blend mode at the middle, eased from either end into
it without a jump, and the phone's fader command checked."""
# AI: below section was generated by an AI
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import numpy as np

from native import mixer, phone

fails = []


def check(ok, what):
    print(("ok   " if ok else "FAIL ") + what)
    if not ok:
        fails.append(what)


a = np.zeros((4, 6, 3), np.uint8); a[..., 0] = 200; a[..., 2] = 40
b = np.zeros((4, 6, 3), np.uint8); b[..., 1] = 180; b[..., 2] = 100
check(np.array_equal(mixer.mix(a, b, 0.0), a) and np.array_equal(mixer.mix(a, b, 1.0), b), "the ends: one deck each")
want = {"crossfade": (100, 90, 70), "add": (200, 180, 140), "screen": (200, 180, 124), "multiply": (0, 0, 16),
        "lighten": (200, 180, 100), "difference": (200, 180, 60)}
for mode, px in want.items():
    got = tuple(int(v) for v in mixer.mix(a, b, 0.5, mode)[0, 0])
    check(all(abs(g - w) <= 1 for g, w in zip(got, px)), f"{mode} at the middle: {got}")
for mode in mixer.MODES:
    seq = [mixer.mix(a, b, f / 100.0, mode).astype(int) for f in range(101)]
    jump = max(int(np.abs(seq[k + 1] - seq[k]).max()) for k in range(100))
    if jump > 12:
        check(False, f"{mode}: a jump of {jump} along the fader")
check(True, "no jump along the fader in any mode")
check(np.array_equal(mixer.mix(a, b[:2], 0.5), a), "decks of two sizes: deck A")
check(phone.check({"a": "fader", "v": 0.25}) == {"a": "fader", "v": 0.25} and phone.check({"a": "fader", "v": "x"}) is None,
      "the phone's fader command checked")

print("FAILED:", fails if fails else "none")
sys.exit(1 if fails else 0)
